using Microsoft.EntityFrameworkCore; using MiniStore.Domain.Entities; using MiniStore.Domain.Interfaces.Accounting; using MiniStore.Infrastructure.Persistence;
namespace MiniStore.Infrastructure.Repositories.Accounting;
public sealed class BankReconciliationRepository(AppDbContext context):IBankReconciliationRepository
{ public Task<BankStatementLine?> GetStatementLineAsync(int id)=>context.BankStatementLines.FirstOrDefaultAsync(x=>x.Id==id); public Task<JournalEntryLine?> GetJournalLineAsync(int id)=>context.JournalEntryLines.FirstOrDefaultAsync(x=>x.Id==id); public Task<decimal> GetActiveStatementAllocationAsync(int id)=>context.BankReconciliationAllocations.Where(x=>x.BankStatementLineId==id&&x.IsActive).SumAsync(x=>(decimal?)x.Amount).ContinueWith(x=>x.Result??0m); public Task<decimal> GetActiveJournalAllocationAsync(int id)=>context.BankReconciliationAllocations.Where(x=>x.JournalEntryLineId==id&&x.IsActive).SumAsync(x=>(decimal?)x.Amount).ContinueWith(x=>x.Result??0m); public Task AddAsync(BankReconciliationAllocation x)=>context.BankReconciliationAllocations.AddAsync(x).AsTask(); public Task SaveChangesAsync()=>context.SaveChangesAsync(); }
